from pathlib import Path
import shutil,json
root=Path(__file__).resolve().parents[1]
out=root/'preview/crawl-reference01'
(out/'assets').mkdir(parents=True,exist_ok=True)
src=root/'engine/upstream/crawl-ref/source/rltiles/dngn'
files={**{f'floor{i}':f'floor/grey_dirt{i}.png' for i in range(8)},**{f'wall{i}':f'wall/brick_dark_1_{i}.png' for i in range(4)},'up':'gateways/stone_stairs_up.png','down':'gateways/stone_stairs_down.png'}
for key,path in files.items():shutil.copyfile(src/path,out/'assets'/f'{key}.png')
m=json.loads((root/'preview/native-layout08/native-maps.json').read_text(encoding='utf-8'))['maps'][1]
(out/'map.js').write_text('const originalMap='+json.dumps(m)+';',encoding='utf-8')
(out/'index.html').write_text('''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>돌죽 원본 지형·계단 참고</title><style>body{margin:0;background:#141916;color:#d9dfd9;font:15px/1.6 system-ui}main{max-width:900px;margin:auto;padding:24px}h1{font-size:25px}p{color:#adc0b0}.scroll{overflow:auto}canvas{display:block;image-rendering:pixelated;max-width:100%;height:auto}#stairs{max-width:600px}a{color:#bcd5bf}button{padding:8px 14px;background:#344537;color:#e8ede8;border:1px solid #6d806b;border-radius:4px;margin-bottom:12px}.raw canvas{max-width:none}</style><main><h1>돌죽 0.34.1 · 원본 지형과 두 종류의 계단</h1><p>기존에 원본 생성기로 추출한 D:5 지도 일부에, 원본 기본 벽·바닥·계단 PNG를 표시했습니다. 계단 위치와 지형은 그대로입니다. 게임 화면 캡처가 아닌 지형 참고 렌더입니다.</p><button id="scale">32×32 원래 크기로 보기</button><div class="scroll" id="frame"><canvas id="field" width="800" height="608"></canvas></div><p>위쪽 작은 공간: 올라가는 계단(54,16) · 아래쪽 길: 내려가는 계단(57,22)</p><canvas id="stairs" width="600" height="160"></canvas><p>돌죽의 굿즈에 해당하는 별도 소품을 임의로 넣지 않았습니다. 이 참고 화면에는 몹·아이템이 없습니다.</p><a href="../city-complete02/">잔향도시 배치로 돌아가기</a></main><script src="map.js"></script><script src="app.js"></script></html>''',encoding='utf-8')
(out/'app.js').write_text('''const images={},keys=[...Array.from({length:8},(_,i)=>'floor'+i),...Array.from({length:4},(_,i)=>'wall'+i),'up','down'];
(async()=>{for(const k of keys)images[k]=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src='assets/'+k+'.png';});const c=document.getElementById('field'),ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;for(let y=10;y<29;y++)for(let x=43;x<68;x++){const f=originalMap.palette[originalMap.rows[y][x]],px=(x-43)*32,py=(y-10)*32,h=((x*374761393)^(y*668265263))>>>0;ctx.drawImage(images[f.includes('wall')?'wall'+h%4:'floor'+h%8],px,py);if(f.includes('stairs_'))ctx.drawImage(images[f.includes('_up_')?'up':'down'],px,py);}const cc=document.getElementById('stairs').getContext('2d');cc.imageSmoothingEnabled=false;cc.fillStyle='#18231a';cc.fillRect(0,0,600,160);['up','down'].forEach((key,i)=>{cc.drawImage(images.floor0,50+i*300,8,96,96);cc.drawImage(images[key],50+i*300,8,96,96);cc.fillStyle='#d8e5d6';cc.font='16px sans-serif';cc.fillText(i?'내려가는 계단 >':'올라가는 계단 <',40+i*300,140);});window.ready=true;})();
document.getElementById('scale').onclick=()=>{const raw=document.getElementById('frame').classList.toggle('raw');document.getElementById('scale').textContent=raw?'화면에 맞춰 보기':'32×32 원래 크기로 보기';};''',encoding='utf-8')
(out/'provenance.json').write_text(json.dumps({'version':'0.34.1','mapSource':'../native-layout08/native-maps.json','mapIndex':1,'crop':[43,10,25,19],'stairs':{'up':[54,16],'down':[57,22]},'art':'unchanged upstream PNGs, default wall and floor families; deterministic illustrative variant choice, not original per-cell tile flavour','isGameScreenshot':False},ensure_ascii=False,indent=2),encoding='utf-8')
print(out)
